local config = {
  str_role_head_image_desc_1001 = "¡Se reconocen tus esfuerzos anteriores! ¿Tomemos algo esta noche para celebrar?",
  str_role_head_image_desc_1002 = "¡Tengo una gran idea! ¿Oh? ¿Tú también? Shh, dejémosla entre nosotros, ¿eh?",
  str_role_head_image_desc_1003 = "Mira a esa persona, ¡genial! ¡Vaya, esa persona! ¡No, no, de ninguna manera!",
  str_role_head_image_desc_1004 = "¡Las cosas vuelven a salir mal! ¿Qué hacer ahora? No quiero maldecir, pero ...",
  str_role_head_image_desc_1005 = "Aah ... maldita sea, ¿cómo pudo pasar esto? Todavía hay margen de mejora, ¡esforcémonos más!",
  str_role_head_image_desc_1006 = "Oh no, estropeamos nuestra tarea. ¿El jefe nos va a regañar? No seamos pesimistas...",
  str_role_head_image_desc_1007 = "No hay nada en la tierra que sea mejor que el otro, solo los seres mundanos se obsesionan con dividirse entre sí.",
  str_role_head_image_desc_1008 = "Aunque a veces no estoy dispuesto, sé que es una cuestión de aceptación. Es la voluntad del destino...",
  str_role_head_image_desc_1009 = "Por favor, no dudes de ti mismo. Todos tienen una misión propia. ¡De eso estoy seguro!",
  str_role_head_image_desc_1010 = "El tiempo es esencial, no lo desperdicies. Haré todo lo posible para ayudarte.",
  str_role_head_image_desc_1011 = "¿Has completado todas las misiones que se te asignaron? Toma esta pequeña flor roja.",
  str_role_head_image_desc_1012 = "Aunque hay mucho trabajo complicado, definitivamente puedo manejarlos todos. ¡Déjamelo a mí!",
  str_role_head_image_desc_1013 = "Si un día pudiera salir de las sombras, supongo que podría...",
  str_role_head_image_desc_1014 = "Definitivamente encontraré el coraje para saludar a alguien hoy. No puedo seguir huyendo. ¡Simplemente no puedo!",
  str_role_head_image_desc_1015 = "Este sonido es tan relajante y eufónico. ¿Quieren escucharlo juntos?",
  str_role_head_image_desc_1016 = "¿Descansaste? ¿Te gustaría la ayuda de Raphaela? No es gran cosa.",
  str_role_head_image_desc_1017 = "No puedo simplemente sentarme y ser una carga. ¿Debería inventar algo nuevo? Quizás algo como...",
  str_role_head_image_desc_1018 = "Argh... ¿Cuándo voy a lograr que la gente confíe en mí? ¿Qué más puedo hacer...?",
  str_role_head_image_desc_1019 = "Aun con un conocimiento tan amplio, es imposible describir lo que sucede. Es simplemente asombroso.",
  str_role_head_image_desc_1020 = "A veces, el fracaso también es una experiencia. Tómalo como un preludio del éxito y no te desanimes.",
  str_role_head_image_desc_1021 = "El futuro de este continente puede estar en tus manos. Creo que puedes hacerlo.",
  str_role_head_image_desc_1022 = "Si eres el primero en despertar y el último en dormir, no eres un Navegador, solo un trabajador de los Aurorians...",
  str_role_head_image_desc_1023 = "¿Por qué tanta prisa? ¿Va por las comidas gratis? Es mejor que te vayas antes de que sea muy tarde.",
  str_role_head_image_desc_1024 = "¡No debemos ver a esos señores elegantes y poderosos desde arriba, o veremos sus cabezas calvas!",
  str_role_head_image_desc_1025 = "¿Por qué estás tratando de matar el tiempo? ¿No hay nada más que hacer?",
  str_role_head_image_desc_1026 = "¿Sabías que es el momento? Nos relajaremos en la escuela, ¡te vas a romper la espalda con el Colossus!",
  str_role_head_image_desc_1027 = "Eres tú de nuevo. ¿Por qué siempre andas con nosotros? ¿No necesitas trabajar?",
  str_role_head_image_desc_1028 = "Eres un tonto ingenuo, por lo que no puedes ser aburrido.",
  str_role_head_image_desc_1029 = "Cuanto más viejo te haces, más torpe eres, y cuanto más alto eres, más torpe te vuelves. Oh, los miserables Lores, ¿por qué no lo ven?",
  str_role_head_image_desc_1030 = "Querido Colossus, ¿por qué te estiras más allá de tu poder y vuelas en el cielo...?",
  str_role_head_image_desc_1031 = "Estéril y frío. Es el destino de las cabezas de los Lores.",
  str_role_head_image_desc_1032 = "¿Por qué no te conoces a ti mismo? ¿Por qué no te miras al espejo? Aquellos que son totalmente inútiles viven en la ignorancia...",
  str_role_head_image_desc_1033 = "Los Lores pueden estar ahí arriba, pero no tiene nada que ver con sus capacidades. Simplemente dependen del poder de los demás.",
  str_role_head_image_desc_1034 = "Por muy cerca que estemos, mi espada no tiene en cuenta a los infractores de la ley.",
  str_role_head_image_desc_1035 = "Cuando miras a la sombra, la sombra te está mirando.",
  str_role_head_image_desc_1036 = "La verdad a menudo está escondida en las nubes, medio cubierta y medio revelada. Tú y yo necesitamos mantener los ojos abiertos.",
  str_role_head_image_desc_1037 = "¿Ordenar? ¿Normas? ¡Ja ja! ¿Que es eso?",
  str_role_head_image_desc_1038 = "El futuro aún es sombrío, pero veo un rayo de esperanza.",
  str_role_head_image_desc_1039 = "¡Bien hecho! ¡Únete a mí en la lucha contra los Eclipsites! ¡Esplendor Ilumina!",
  str_role_head_image_desc_1301 = "¡Nada mal! Oye, ¿quieres unirte a Rediesel Wrench?",
  str_role_head_image_desc_1302 = "Gracias a todos, mis fuerzas han vuelto... ¿Quieres que me encargue de algunos Eclipsites?",
  str_role_head_image_desc_1303 = "Disfruta de los cerezos en la Montaña Nube conmigo.",
  str_role_head_image_desc_1304 = "Un tazón fino de granizado con cerebro Congelado garantiza el mejor refrigerio bajo el sol de verano.",
  str_role_head_image_desc_1305 = "¡Ponte esto y conviértete en Acero Rediesel MkV Zero!",
  str_role_head_image_desc_1306 = "¿Eh..? ¿Todos se han ido a divertir? Bueno, supongo que yo también debería ir...",
  str_role_head_image_desc_1307 = "¿Necesitas refrescarte? ¡Permíteme! ¡Flor de hielo!",
  str_role_head_image_desc_1308 = "¿Ya se han pasado cien días? ¡Esto merece una torta!",
  str_role_head_image_desc_1309 = "Hmm. La verdad es que el desierto está me tomando.",
  str_role_head_image_desc_1310 = "¿Por qué siento mi cabeza tan pesada? Oh, son ellos... Bien, solo dejaré...",
  str_role_head_image_desc_1311 = "¿Ganamos? ¡Agarra el cañón de fuegos! ¡Es hora de celebrar!",
  str_role_head_image_desc_1312 = "Espero que tu yo podamos llegar a un acuerdo sobre esto.",
  str_role_head_image_desc_1313 = "¿Quieres ver la cara bajo de la máscara? Eso se puede arreglar... Todo lo que tienes que hacer es unirte a mi grupo de mercenarios.",
  str_role_head_image_desc_1314 = "Noche Blanca en lo alto... Un día, deseo eliminar toda injusticia en el mundo.",
  str_role_head_image_desc_1315 = "¡Representa el mayor honor de la arena subterránea de Umbraton! ¡Prueba innegable de que eres un maestro del combate!",
  str_role_head_image_desc_1316 = "¡Na-Na-Navegador! ¡Déjame enseñarte algo de magia!",
  str_role_head_image_desc_1317 = "Una sonrisa tan traviesa... ¡Vamos a sembrar el caos!",
  str_role_head_image_desc_1318 = "¡Me encontré con un lindo gatito durante mi patrulla! ¡Hoy es un buen día!",
  str_role_head_image_desc_1319 = "Es un símbolo de autoridad en Lumópolis, generalmente reservado para los nobles.",
  str_role_head_image_desc_1320 = "Así es como se viste la gente de Northland para el Año Nuevo, y yo no soy una excepción.",
  str_role_head_image_desc_1321 = "Les deseo paz y felicidad en el Año Nuevo.",
  str_role_head_image_desc_1322 = "¡Ahora sabes que soy la mejor sirvienta de todas!",
  str_role_head_image_desc_1323 = "Una niña educada será amable incluso cuando duerma. No se moverá, e incluso podrías colocarle una naranja en la cabeza mientras duerme.",
  str_role_head_image_desc_1324 = "Lentamente y con precisión, los sacaré…",
  str_role_head_image_desc_1325 = "Mirando esto... ¡debe tener al menos mil años!",
  str_role_head_image_desc_1326 = "¿Buscas celebrar? Cada festival tiene sus propias características especiales",
  str_role_head_image_desc_1327 = "¡Oye! ¿Quieres dar una vuelta conmigo?",
  str_role_head_image_desc_1328 = "Un cuaderno siempre es mejor que un buen recuerdo.",
  str_role_head_image_desc_1329 = "*aullidos* ¡Espero que no te hayas asustado!",
  str_role_head_image_desc_1330 = "El amor es precioso,\nLa libertad es más.\nAmbos pueden ser entregados,\nPor el bien de un voto.",
  str_role_head_image_desc_1331 = "jingles! ¿Quieres un tintineo miau?",
  str_role_head_image_desc_1332 = "Por favor escucha el sonido de la Kagura Bell.",
  str_role_head_image_desc_1333 = "¡No le voy a dar el bollo a nadie!",
  str_role_head_image_desc_1334 = "¿Estás despierto? ¡Ponte a trabajar entonces!",
  str_role_head_image_desc_1335 = "¡Victoria! ¿Quieres ir a divertirte para celebrar?",
  str_role_head_image_desc_1336 = "Se parece a mí, ¿verdad?",
  str_role_head_image_desc_1338 = "Ah ah ah. La cabeza de gatito te está mirando.",
  str_role_head_image_desc_1339 = "¿En qué se diferencian?",
  str_role_head_image_desc_1340 = "Siempre me has cuidado bien, así que por favor acepta esto.",
  str_role_head_image_desc_1341 = "Escuché que hoy es el día para expresar nuestros corazones... ¿así?",
  str_role_head_image_desc_1342 = "Escuché que este pijama es tendencia actualmente entre los Navegantes. ¡Hice cola durante mucho tiempo para conseguirlo!",
  str_role_head_image_desc_1343 = "El color de mis ojos... ha cambiado.",
  str_role_head_image_desc_1344 = "Hmm... ¿Me olvidé de hacer algo?",
  str_role_head_image_desc_1345 = "Escribir asuntos de gran importancia es un buen hábito para el Jefe de Gabinete.",
  str_role_head_image_desc_1346 = "¿Este equipo? Lo recogí mientras compraba en Umbraton. ¿No es simplemente único?",
  str_role_head_image_desc_1347 = "El Chubb Merchant parece haber recibido un gran regalo y canta de felicidad.",
  str_role_head_image_desc_1348 = "¡Ilumina te necesita! ¡Esperamos contar con usted!",
  str_role_head_image_desc_1349 = "¿Mmm? ¿Quieres oírme cantar? Por supuesto. ¡Pero a cambio, tienes que jugar conmigo!",
  str_role_head_image_desc_1350 = "¿Por qué me disfrazé de Yumi? Porque ella es súper linda.",
  str_role_head_image_desc_1351 = "¿Las orejas? Philyshy me hizo usar estos o ella me denunciaría al oficial Sharona por pisarle la cola sin querer...",
  str_role_head_image_desc_1352 = "¡Haz equipo conmigo! ¡Nunca perderás!",
  str_role_head_image_desc_1353 = "¿Eh? ¿Qué tiene eso de difícil?",
  str_role_head_image_desc_1354 = "Usted también debe tomar un descanso de vez en cuando.",
  str_role_head_image_desc_1355 = "¿Donde estaba?",
  str_role_head_image_desc_1356 = "¡Aghhh! ¡Hace tanto calor!",
  str_role_head_image_desc_1357 = "Es un verano caluroso y usar un sombrero para el sol es una excelente manera de prevenir las quemaduras solares. Cuidado con el calor, Navegante.",
  str_role_head_image_desc_1358 = "¿Quién diría que no a una taza de hielo raspado frío y delicioso en un caluroso día de verano?",
  str_role_head_image_desc_1359 = "En este caluroso verano, siempre puedes sentir un poco de frescura al lado de Carleen.",
  str_role_head_image_desc_1360 = "Es muy acogedor aquí. Disfrutemos del silencio en medio de la fiesta.",
  str_role_head_image_desc_1361 = "La noche es mi amiga y los murciélagos mis súbditos. ¿Quién, entonces, soy yo?",
  str_role_head_image_desc_1362 = "¡No tengas miedo! Me hice este farol de calabaza para animar el ambiente del evento durante los próximos días. No está mal, ¿verdad?",
  str_role_head_image_desc_1363 = "¡Déjame ver qué ha pasado!",
  str_role_head_image_desc_1364 = "Es muy grave, pero todavía se permite que una serpiente se quede en mi cabeza.",
  str_role_head_image_desc_1365 = "¿Quieres comprar dulces? Intercambia tus historias por ellos.",
  str_role_head_image_desc_1366 = "No te importaría que te vista como un lobo, ¿verdad?",
  str_role_head_image_desc_1367 = "Caronte se puso con entusiasmo dientes postizos y una capa. ¡El espectáculo está en marcha!",
  str_role_head_image_desc_1368 = "Para Hiiro, convertirse en mago también puede servir como un tipo de entrenamiento.",
  str_role_head_image_desc_1369 = "Paloma se envuelve en vendas para sorprender a todos los niños que vienen a pedir dulces.",
  str_role_head_image_desc_1370 = "Esta moneda... representa mi pasado.",
  str_role_head_image_desc_1371 = "Estas luces de varios colores son tan hermosas.",
  str_role_head_image_desc_1372 = "¡Ven conmigo y conviértete en un ídolo!",
  str_role_head_image_desc_1373 = "Listo... ¡Acción!",
  str_role_head_image_desc_1374 = "Philyshy dijo que cambió un poco de pescado seco por estos populares pijamas de Año Nuevo. Son muy cómodos, pero ¿por qué tienen orejas?",
  str_role_head_image_desc_1375 = "Los fideos de caracol de río, con su aroma único, son la comida favorita de Mu Yuebai.",
  str_role_head_image_desc_1376 = "No te ves muy bien. ¿Quieres que te echemos un vistazo?",
  str_role_head_image_desc_1377 = "Observar en silencio a las personas y las cosas es una especie de hábito para Jeriah.",
  str_role_head_image_desc_1378 = "Con su semblante siempre recto, Michael se apodera de todas las rosas que ella ve.",
  str_role_head_image_desc_1379 = "Saludar al mundo con un disfraz llamativo a veces puede ofrecer una experiencia completamente diferente.",
  str_role_head_image_desc_1380 = "Peligroso. Por favor, no imites.",
  str_role_head_image_desc_1381 = "Jeno te está invitando a tomar una taza de café solo con él. ¿Aceptas su invitación?",
  str_role_head_image_desc_1382 = "Un juez de Lumopolis debe tener el coraje de tomar la decisión final.",
  str_role_head_image_desc_1383 = "Este muñeco se parece a mí, así que me siento seguro mientras lo abrazo.",
  str_role_head_image_desc_1384 = "Me gusta esta música porque me tranquiliza.",
  str_role_head_image_desc_1385 = "Yingel, que está muy cerca de los papamoscas, debe ser muy gentil.",
  str_role_head_image_desc_1386 = "Usa tu espada para expandir las fronteras y tus manos para consolar los corazones de la gente. Leo se adhiere firmemente a este principio.",
  str_role_head_image_desc_1387 = "El aroma del té negro es calmante para Mia y la ayuda a relajarse.",
  str_role_head_image_desc_1388 = "¿De quién es la flor favorita de las violetas en sus manos?",
  str_role_head_image_desc_1389 = "¿Qué ves en la bola de cristal? ¿El pasado o el futuro?",
  str_role_head_image_desc_1501 = "Esta flor del amanecer representa la esperanza. ¡Úsalo y disipa la tristeza de tu pasado!",
  str_role_head_image_desc_1502 = "El emblema de la familia Sakura. Representa el reconocimiento de Hiiro hacia ti.",
  str_role_head_image_desc_1503 = "Si necesitas la ayuda de este misterioso guerrero, contacta al Trabajos Ocasionales de Sr. Taki.",
  str_role_head_image_desc_1504 = "Heehee... ¿Qué tal si tomamos juntos el té de la tarde?\n¿O no puedes con siete barriles de té?",
  str_role_head_image_desc_1505 = "Sumérgete en la oscuridad eterna conmigo.",
  str_role_head_image_desc_1506 = "¿No puedes luchar contra los Eclipsites? No te preocupes — ¡yo lo haré por ti!",
  str_role_head_image_desc_1507 = "¡Una sorpresa de Windelion!¿Qué obsequios fascinantes contiene?",
  str_role_head_image_desc_1508 = "Tómate una copa conmigo y disfrutemos juntos de esta maravillosa noche.",
  str_role_head_image_desc_1509 = "Tú... Parece que necesitas mi ayuda.",
  str_role_head_image_desc_1510 = "Te lo digo ahora, esta comida fue hecha para Kobayashi. ¡Será mejor que no la toquen!",
  str_role_head_image_desc_1511 = "¿Yo? he estado durmiendo temprano...",
  str_role_head_image_desc_1512 = "Ahh... tengo sed... ¿Dónde está el agua?",
  str_role_head_image_desc_1513 = "¿De verdad me estás preguntando qué pienso de Navigator...?",
  str_role_head_image_desc_1514 = "¿Dónde más puedo encontrar comida deliciosa?",
  str_role_head_image_desc_1515 = "¡Vamos a dar un paseo!",
  str_role_head_image_desc_1516 = "¿Alguien puede entender Lenore?",
  str_role_head_image_desc_1517 = "Estrategias futuras...",
  str_role_head_image_desc_1518 = "La hora del té de la tarde es el momento más alegre del día.",
  str_role_head_image_desc_1519 = "roger",
  str_role_head_image_desc_1520 = "¿Es mi turno?",
  str_role_head_image_desc_1521 = "Lumopolis y el continente... Definitivamente no lo haremos y no debemos volvernos así.",
  str_role_head_image_desc_1522 = "¿Algo en tu mente? ¡Refrescarnos juntos en el agua!",
  str_role_head_image_desc_1523 = "¡Vamos, hagamos un partido!",
  str_role_head_image_desc_1524 = "Uf... Todo listo.",
  str_role_head_image_desc_1525 = "¿Sobrevivir o perecer?\nEsa es la pregunta.",
  str_role_head_image_desc_1526 = "¡Aquí viene la inspiración! ¡Entiendo! ¡Este va a ser un gran éxito!",
  str_role_head_image_desc_1527 = "El espadachín desciende en picado con un casquete; son Sadie y Coolster, castigando a los malos y cantando rap.",
  str_role_head_image_desc_1530 = "¡Tu temperamento realmente puede mejorar cuando cultivas flores!",
  str_role_head_image_desc_1531 = "Ella es hermosa pero también muy... peligrosa.",
  str_role_head_image_desc_1532 = "¡Ay! Tan cálido... ¡Tan suave!",
  str_role_head_image_desc_1533 = "Parece que todavía está absorta en esa vieja historia. No la molestemos.",
  str_role_head_image_desc_1534 = "¡Feliz año nuevo! ¡Vamos a lanzar algunos fuegos artificiales!",
  str_role_head_image_desc_1535 = "Este barco... es tan atractivo.",
  str_role_head_image_desc_1536 = "¡Rico rico! ¿Hay más?",
  str_role_head_image_desc_1537 = "¡Voy a llegar tarde! ¡Supongo que tendré que comer mientras camino de nuevo hoy!",
  str_role_head_image_desc_1538 = "No estoy durmiendo... Zzz...",
  str_role_head_image_desc_1539 = "¿Puedes borrarlo de una vez?",
  str_role_head_image_desc_1540 = "Madre... Padre...",
  str_role_head_image_desc_1541 = "Ese desagradable criminal... ¡No dejaré que te escapes!",
  str_role_head_image_desc_1542 = "¿Dónde está mi presa? ¡Justo en frente de mí, por supuesto!",
  str_role_head_image_desc_1543 = "Siempre es mejor una libreta que un buen recuerdo...",
  str_role_head_image_desc_1544 = "¡El Ejercicio Militar Conjunto comienza ahora!",
  str_role_head_image_desc_1545 = "No pase por alto nada ya que los detalles importan.",
  str_role_head_image_desc_1601 = "Un escudo de torre agrietado llevado exclusivamente por los Caballeros Lumo. Con forma de cometa, es ancha en la parte superior y estrecha en la parte inferior, con bordes bien definidos y una superficie grabada con el emblema de la iglesia.",
  str_role_head_image_desc_1602 = "Un árbol muerto con tres bolas de colores colgando de él. Para Martha, el pasado se ha marchitado, y en este reino nevado salpicado de luces, una vez más dará la bienvenida a una nueva vida.",
  str_role_head_image_desc_1603 = "Hay un engranaje en el centro del neumático. Rosa se había adentrado en el desierto y quienes seguían el rastro ya no podían encontrarla, solo las huellas dejadas por las llantas.",
  str_role_head_image_desc_1604 = "Entre los lirios en flor se encuentra una hoja afilada. Según los escritos de Yvonne, el destino de la Sra. Red Mercury está escondido en la niebla. Nadie sabe si regalará su espada o el lirio en sus mangas.",
  str_role_head_image_desc_1901 = "Soroz no es solo un Colossus. Es un amigo que te ha hecho compañía durante 17 años.",
  str_role_head_image_desc_1902 = "Usar este casco te hace sentir como un guardián de la Noche Blanca. ¿Qué tipo de Noche Blanca? No vayamos al fondo de eso.",
  str_role_head_image_desc_2001 = "Este emblema personal pertenece a Korgon.",
  str_role_head_image_desc_2002 = "Este emblema personal pertenece a Chainsaw Rick.",
