  str_role_head_image_frame_lock_condition_104 = "Obtiene 1,000,000 Nightium",
  str_role_head_image_desc_frame_1000 = "Marco de avatar por defecto. El marco inicial de todo Navegador.",
  str_role_head_image_desc_frame_2001 = "Este antiguo patrón representa el reconocimiento de los Cazadores Silenciosos hacia ti. Acepte este supremo honor del pasado.",
  str_role_head_image_desc_frame_2002 = "¡Decora tu Avatar con exquisitos accesorios!",
  str_role_head_image_desc_frame_3001 = "Bajo el sol abrasador, encima de las olas azules, los recuerdos inolvidables permanecerán para siempre en esta playa caliente y húmeda.",
  str_role_head_image_desc_frame_3002 = "Usa esta boina y parecerás un excelente soldado Illumina.",
  str_role_head_image_desc_frame_3003 = "¿Quién no necesita ayuda a la hora de sopesar los pros y los contras de un asunto?",
  str_role_head_image_desc_frame_3004 = "¿Quieres ser el alma de la fiesta? ¡Esto es todo lo que necesitas!",
  str_role_head_image_desc_frame_3005 = "¡Una pancarta dedicada a los buenos estudiantes! ¡Seguid así!",
  str_role_head_image_desc_frame_3007 = "Te haremos compañía....",
  str_role_head_image_desc_frame_3008 = "¡El premio de la pesca!",
  str_role_head_image_desc_frame_3010 = "¡Es el aroma de la primavera!",
  str_role_head_image_desc_frame_3011 = "¡Siento que esto me ayudará a convertirme en un gran corredor!",
  str_role_head_image_desc_frame_3012 = "Debajo de la cortina escarlata hay una canción infantil oscura...",
  str_role_head_image_desc_frame_3013 = "La llamativa corona es una muestra de honor y dignidad.",
  str_role_head_image_desc_frame_3014 = "¡Exclusivamente para el Gran Mariscal!",
  str_role_head_image_desc_frame_3015 = "¿Usar esto mejorará las habilidades de hospitalidad de uno?",
  str_role_head_image_desc_frame_3018 = "¡Es el aniversario de 1 año! ¡Póntelo y sal a celebrar!",
  str_role_head_image_desc_frame_3019 = "¡Solo ponte esto y te verás todo borroso como un Bica!",
  str_role_head_image_desc_frame_3020 = "¡No te preocupes, no hace calor!",
  str_role_head_image_desc_frame_3021 = "¡Usa esto, el gran mago!",
  str_role_head_image_desc_frame_3022 = "El sol es muy fuerte, ¡así que cuídate y no te quemes!",
  str_role_head_image_desc_frame_3023 = "¿Parece que la garra de un murciélago te está agarrando la cabeza? La diadema está demasiado apretada.",
  str_role_head_image_desc_frame_3024 = "Dicen que llevar esta gorra te ayuda a rapear mejor. Sorprendentemente, también mejora tus habilidades de béisbol.",
  str_role_head_image_desc_frame_3025 = "Imprescindible para cualquier cantante. ¡Sumérgete en la música!",
  str_role_head_image_desc_frame_3026 = "No es para comer, ¡es para vestir!",
  str_role_head_image_desc_frame_3027 = "¿Usar esto realmente te hará tan fuerte como Jeriah? Una cosa es segura, al menos te mantendrá a salvo del viento...",
  str_role_head_image_desc_frame_3028 = "En realidad, es un par de anteojos con lentes transparentes.",
  str_role_head_image_desc_frame_3029 = "¡Ajá! ¡Él es el culpable!",
  str_role_head_image_desc_frame_3031 = "¿Existe realmente ese mundo? Si no es así, ¿por qué estoy aquí?",
  str_role_head_image_frame_lock_condition_2001 = "Desbloqueo al completar la etapa Sello viejo - Cementerio silencioso.",
