  str_role_head_image_lock_condition_role_1391 = "Obtenido del evento",
  str_role_head_image_lock_condition_role_1392 = "Obtenido del evento",
  str_role_head_image_desc_1390 = "Cuando estás triste, ¿un abrazo suave podría mejorarlo?",
  str_role_head_image_desc_1391 = "Sea mi audiencia o sea mi socio, ¿cuál es su elección?",
  str_role_head_image_desc_1392 = "¡Refresca el calor del verano con un refrescante tazón de hielo raspado!",
  str_role_head_image_desc_1547 = "Verlos así me hace feliz.",
  str_role_head_image_lock_condition_role_1548 = "Obtenido del evento Espino Ardiente en Flor.",
  str_role_head_image_lock_condition_role_1549 = "Compra el Libro Especial Event: Fase 16 Edición Deluxe para desbloquear.",
  str_role_head_image_lock_condition_role_1550 = "Obtenido del evento Contador de registro de invitados.",
  str_role_head_image_desc_1548 = "¿Sientes el impulso? Entonces simplemente disfruta con apertura y confianza.",
  str_role_head_image_desc_1549 = "¿Realmente el peligro amplifica la belleza?",
  str_role_head_image_desc_1550 = "¡Ideas sólidas y acción forman la base del éxito!",
  str_role_head_image_frame_lock_condition_3041 = "Obtenido del evento Espino Ardiente en Flor.",
  str_role_head_image_frame_lock_condition_3042 = "Compra el Libro Especial Event: Fase 16 Edición Deluxe para desbloquear.",
  str_role_head_image_desc_frame_3041 = "Parece fácil pincharse; ¿quién estaría dispuesto a usarlo...",
  str_role_head_image_desc_frame_3042 = "¿Eso es lo que quieres decir con ser un caballero?",
  str_role_head_image_lock_condition_role_1393 = "Obtenido del evento",
  str_role_head_image_lock_condition_role_1394 = "Obtenido del evento",
  str_role_head_image_lock_condition_role_1395 = "Obtenido del evento",
  str_role_head_image_desc_1393 = "Tengo una idea genial para ganar dinero. ¿Quieres probar?",
  str_role_head_image_desc_1394 = "¿Quieres saber qué me hace reír? Adelante, ¡intenta adivinar!",
  str_role_head_image_desc_1395 = "¿Mi postre favorito de verano? Bueno, probablemente es helado con trozos de carne de lagarto espolvoreados encima.",
  str_role_head_image_desc_1551 = "¿No podemos tener una conversación que no involucre informes de trabajo?",
  str_role_head_image_lock_condition_role_1551 = "Obtenido en Una Sinfonía en el Crepúsculo.",
  str_role_head_image_desc_1396 = "¿Ojeras? Para nada.",
  str_role_head_image_desc_1397 = "May la luz brilla sobre el Pueblo del Crepúsculo, disipando las sombras que allí se encuentran.",
  str_role_head_image_lock_condition_role_1396 = "Obtenido del evento",
  str_role_head_image_lock_condition_role_1397 = "Obtenido del evento",
  str_role_head_image_lock_condition_role_3755023 = "Obtenido en el Despertar de la Tormenta.",
  str_role_head_image_lock_condition_role_3755024 = "Obtenido en el Despertar de la Tormenta.",
  str_role_head_image_desc_3755023 = "*gemidos*... ¿Te gusto?",
  str_role_head_image_desc_3755024 = "¿Diente de león? ¡No huyas de mí!",
  str_role_head_image_frame_lock_condition_3755025 = "Obtenido en el Despertar de la Tormenta.",
  str_role_head_image_desc_frame_3755025 = "Aunque pequeña, esta flor blanca representa el amanecer...",
  str_role_head_image_desc_1552 = "\"¡Basta de esa broma del polo de hielo!\"",
  str_role_head_image_lock_condition_role_1552 = "Obtenido del evento Diario de Exploración.",
  str_role_head_image_desc_1553 = "\"Con las vacaciones acercándose, ya tengo todos mis planes de vacaciones listos. ¿Quieres saber cuál es el plan de Tweety?\"",
  str_role_head_image_lock_condition_role_1553 = "Obtenido del evento de inicio de sesión Golden Autumn.",
  str_role_head_image_desc_1398 = "\"Oh, el cielo nocturno... es como una biblioteca infinita, que guarda todos los secretos del mundo.\"",
  str_role_head_image_desc_1399 = "\"Quizás algún día, pueda manejar con delicadeza este poder que el destino me ha otorgado.\"",
  str_role_head_image_desc_1400 = "\"¿Eh?\"",
  str_role_head_image_desc_1040 = "\"Negador, Reinhardt... Pase lo que pase, que cada uno encuentre su propio camino.\"",
  str_role_head_image_desc_1041 = "\"No tengo intención ni interés en hacer enemigos; simplemente son obstáculos en mi camino.\"",
  str_role_head_image_desc_1042 = "\"La Iluminación Iluminada puede ser cualquiera: tú, yo, quien sea, siempre y cuando guíen a los Aurorianos a través de los desafíos.\"",
  str_role_head_image_frame_lock_condition_3043 = "Compra el libro de eventos especiales: Phase 17 Deluxe Edition para desbloquearlo.",
  str_role_head_image_desc_frame_3043 = "Zarya estaba preocupada de que el frío intenso de Northland pudiera ser demasiado para ti, así que te dio su gorro.",
  str_role_head_image_desc_1401 = "Lihat layup tiga langkah saya! Ya ampun! Kenapa harus langsung terpental dari papan belakang?!",
  str_role_head_image_desc_1402 = "Olahraga adalah kehidupan! Bahkan jika saya seorang pemula, saya akan memberikan semua yang saya punya di meja pingpong!",
  str_role_head_image_desc_1403 = "Dalam hal bermain game, saya tidak akan pernah ketinggalan! Lihat saja saya memiliki para pemula itu di kompetisi esports besar berikutnya!",
  str_role_head_image_desc_1404 = "Tahukah kamu? Saya juga selalu tampil luar biasa di lapangan tembak!",
  str_role_head_image_lock_condition_role_3755036 = "Obtenido del evento Pruebas Entre Ondas Doradas",
  str_role_head_image_lock_condition_role_3755037 = "Obtenido del evento Pruebas Entre Ondas Doradas",
  str_role_head_image_desc_3755036 = "¡No dejaré que se me escape ninguna pista!",
  str_role_head_image_desc_3755037 = "Puede que no se vea elegante, pero confía en mí, ¡sabe fantástico!",
  str_role_head_image_desc_3755004 = "\"Las perlas brillan suavemente, gracia de la luz matutina; Flores en silencio, un abrazo delicado; ¿El mundo percibe, esta exquisita persecución?\"",
  str_role_head_image_lock_condition_role_3755004 = "Obtenido del evento de inicio de sesión de Warm Winds",
  str_role_head_image_desc_1405 = "\"Por favor, toma asiento y déjame echar un vistazo.\"",
  str_role_head_image_desc_1406 = "\"¡Perseguiré a cualquiera que se atreva a deberte dinero y no pagar!\"",
  str_role_head_image_desc_1407 = "Un tesoro enterrado profundamente en el océano.\nResiste el desgaste constante y la erosión del agua de mar, todo con la esperanza de algún día emerger en tierra.",
  str_role_head_image_desc_1408 = "Los Caelestites tenían algunas creencias similares a las de mi propio pueblo. ¿Te interesaría visitar Ye para un intercambio cultural?",
  str_role_head_image_desc_1554 = "*Tos, tos*... E-Estoy bien... solo necesito descansar un poco.",
  str_role_head_image_desc_1555 = "\"¡Hoy invito yo!\"",
  str_role_head_image_desc_1556 = "\"Una creación de maquinaria sin función práctica. Si la encuentras estéticamente agradable, entonces vale la pena tenerla.\"",
  str_role_head_image_desc_frame_3044 = "\"No te preocupes, no te hará daño...\"",
  str_role_head_image_frame_lock_condition_3044 = "Compra el libro de eventos especiales: Phase 18 Deluxe Edition para desbloquearlo.",
  str_role_head_image_lock_condition_role_1554 = "Obtenido del evento Golden Idol",
  str_role_head_image_lock_condition_role_1555 = "Obtenido del evento Joyous Journey",
  str_role_head_image_lock_condition_role_1556 = "Obtenido del evento Berth Sign-In.",
  str_role_head_image_lock_condition_role_1557 = "Obtenido del evento de inicio de sesión de Visitor.",
  str_role_head_image_lock_condition_role_1558 = "Obtenido del evento Countdown Gift.",
  str_role_head_image_desc_1409 = "\"Aunque esto no es ni el 1% de mi riqueza, no hay razón para decir no al dinero gratis.\"",
  str_role_head_image_desc_1410 = "\"Casi son las vacaciones. Debería relajarme un poco.\"",
  str_role_head_image_desc_1411 = "\"Son las tres en punto. ¿Quieres una taza de té?\"",
  str_role_head_image_desc_1557 = "\"No dudes. Sorprende a tus enemigos y gana.\"",
  str_role_head_image_desc_1558 = "\"Esta moneda de la suerte es para ti, que estás garantizado de ser bendecido con suerte en el próximo año.\"",
  str_role_head_image_desc_frame_3045 = "\"Esta serpiente humeante y enroscada eventualmente devorará todo.\"",
  str_role_head_image_frame_lock_condition_3045 = "Compra el libro de eventos especiales: Phase 19 Deluxe Edition para desbloquearlo.",
  str_role_head_image_lock_condition_role_1559 = "Obtenido del evento Pétalos Efímeros Sobre Cenizas.",
  str_role_head_image_lock_condition_role_1560 = "Obtenido del evento de inicio de sesión de Navigation.",
  str_role_head_image_desc_1559 = "\"Un color extraño se proyecta en la cara de Hiiro, probablemente por el color de las flores de cerezo que han florecido temprano en un lugar distante.\"",
  str_role_head_image_desc_1560 = "\"La sabiduría me sacia, no la comida.\"",
  str_role_head_image_desc_1412 = "\"Los Aurorianos son su propio enemigo.\"",
  str_role_head_image_desc_frame_3046 = "La línea de sangre de la Familia Sakura ha estado guardando silenciosamente Hiiro en nombre del resto del clan.",
  str_role_head_image_frame_lock_condition_3046 = "Obtenido del evento Pétalos Efímeros Sobre Cenizas.",
  str_role_head_image_desc_1561 = "\"¿Quién puede resistirse a la tentación de frotar su cabeza contra un tigrito tan lindo con poderes tan deliciosos?\"",
  str_role_head_image_desc_1562 = "\"Este nivel de picante no es nada para Rediesel Wrench.\"",
  str_role_head_image_desc_1563 = "\"A la gente de Ye le gustan los platos picantes. Aunque el ultra picante es un poco demasiado para Dantang, ella es una excelente cocinera y puede entender la belleza de este sabor.\"",
  str_role_head_image_desc_1564 = "\"¡Siempre debes comer de manera elegante! Carleen se recuerda constantemente que no puede olvidar la etiqueta de cena de los Caballeros de Lumo solo por la estimulación en su boca.\"",
  str_role_head_image_desc_1565 = "\"¡Ahhhhhhhhh! ¡Astra picante! Eso fue lo primero que dijo el estornino después de comer la salsa de chile.\"",
  str_role_head_image_desc_1413 = "\"Tengo una larga lista de cosas que me gustaría ver: la armadura mecanizada gigante en Azurite, los ruidosos espectáculos en el desierto, las intensas peleas subterráneas...\"\nIncluso una deidad tiene muchos deseos para el Año Nuevo.",
  str_role_head_image_desc_1414 = "¡Cuidado con la bestia Nian de Umbraton, un verdadero devorador de hombres con largos cuernos! Echa un vistazo a \"Feria del Templo Prohibido\", la última película de terror de Alleywood, que se estrena esta primavera!\n\"Entonces... ¿cuál es mi papel de nuevo...?\"",
  str_role_head_image_desc_1415 = "\"Aquí tienes, solo algo que preparé... ¡Puedo hacer cosas aparte de paletas, sabes!\"\nLo único que Zarya logró hacer con éxito después de innumerables fracasos, con un extra de dulzura para manifestar sus sentimientos.",
  str_role_head_image_desc_1416 = "Esperando que el reencuentro de hoy te brinde una sensación de hogar y fortaleza. Es el mismo cielo sobre nosotros, estemos donde estemos.",
  str_role_head_image_desc_1417 = "\"¡Caelestite recibió un sombrero especial como regalo de Año Nuevo y se lo puso felizmente!\"",
  str_role_head_image_desc_1566 = "\"¡Chen'ni otorga bendiciones, concediendo riqueza y prosperidad!\"\n¿Puede la Doncella Dragón, venerada como una deidad marina, realmente otorgar felicidad al mundo mundano? Chen'ni puede que no lo sepa, ¡pero está decidida a intentarlo!",
  str_role_head_image_desc_1567 = "\"¡Mi paladar es el estándar!\"\nComo enviado de Astra, el Navegante tiene mucha experiencia en la degustación de alimentos, presumiendo de un paladar refinado.",
  str_role_head_image_desc_1568 = "\"Aunque muchos expresan su cariño por mí, encuentro al Navegante el más especial. ¡Realmente compartimos una conexión de corazón a corazón!\"",
  str_role_head_image_desc_1569 = "\"¿Corazón con la mano, en serio?... Está bien, toma este gesto mío y agradece... ¡pero no te emociones demasiado!\"",
  str_role_head_image_lock_condition_role_1566 = "Obtenido del evento Avance de Fin de Año",
  str_role_head_image_lock_condition_role_1567 = "Obtenido del evento Cooking Frenzy",
  str_role_head_image_desc_frame_3047 = "\"Las flores de melocotón son delicadas y graciosas, irradiando su resplandeciente belleza. Y la fortuna llega, en su vibrante abrazo.\"",
  str_role_head_image_desc_frame_3048 = "\"¡Recolecta todas las Cartas de Primavera para invocar al dragón divino!\"\nNo estoy seguro si es cierto, pero esta locura de coleccionar cartas hizo que el Año Nuevo de Longzhou fuera mucho más divertido.",
  str_role_head_image_frame_lock_condition_3047 = "Compra el libro de eventos especiales: Phase 20 Deluxe Edition para desbloquearlo.",
  str_role_head_image_frame_lock_condition_3048 = "Obtenido del evento Spring Cards: ¡Colecciónalos todos!",
  str_role_head_image_frame_lock_condition_3049 = "Obtenido del evento Hechizo de la Noche Embrujada.",
  str_role_head_image_frame_lock_condition_3050 = "Obtenido del evento",
  str_role_head_image_desc_frame_3049 = "\"Mi atuendo estallará en llamas cuando la poción se desvanezca. ¿Seguirás el último rastro del fuego hasta mí?\"",
  str_role_head_image_desc_frame_3050 = "\"¡Aquellos que son firmes serán recompensados con gloria!\"\nGracias por tu guía y protección durante mil días de perseverancia y compañía. Esperamos futuras aventuras juntos.",
  str_role_head_image_lock_condition_role_1570 = "Obtenido del evento Hechizo de la Noche Embrujada.",
  str_role_head_image_desc_1570 = "\"¿Quieres estar en el Limbo conmigo? ¡Toma mi mano entonces, y dejemos que nuestras esperanzas ardan brillantes!\"",
  str_role_head_image_desc_1418 = "\"Navegador, gracias por acompañarme durante mil días bajo este cielo. ¡Por favor, continúa guiándome en el futuro!\"",
  str_role_head_image_desc_1419 = "\"¿También quieres participar en la prueba especial del Día de la Corona de Luna?\"",
  str_role_head_image_desc_1420 = "\"¡Navegante, por aquí!\"\nEl amor ha sido tu compañero constante en este viaje durante mil días. ¡Sigue avanzando con las bendiciones de todos!",
  str_role_head_image_desc_1421 = "\"¡Aprovecha el momento; hoy podría ser el punto de inflexión en nuestro destino!\"",
  str_role_head_image_frame_lock_condition_3051 = "Compra el libro de eventos especiales: Phase 21 Deluxe Edition para desbloquearlo.",
  str_role_head_image_desc_frame_3051 = "\"Parece algo familiar.\"",
  str_role_head_image_lock_condition_role_1571 = "Obtenido del evento de inicio de sesión de Navigation.",
  str_role_head_image_desc_1571 = "\"¿Te has escondido? Todavía no.\"",
  str_role_head_image_lock_condition_role_1043 = "Se desbloquea después de 1,050 días de inicio de sesión",
  str_role_head_image_lock_condition_role_1044 = "Se desbloquea después de 1,100 días de inicio de sesión",
  str_role_head_image_lock_condition_role_1045 = "Se desbloquea después de 1,150 días de iniciar sesión",
  str_role_head_image_lock_condition_role_1046 = "Se desbloquea después de 1,200 días de inicio de sesión",
  str_role_head_image_lock_condition_role_1047 = "Se desbloquea después de 1,250 días de iniciar sesión",
  str_role_head_image_lock_condition_role_1048 = "Se desbloquea después de 1,300 días de iniciar sesión",
  str_role_head_image_lock_condition_role_1049 = "Se desbloquea después de 1,350 días de inicio de sesión",
  str_role_head_image_desc_1043 = "\"Entiendo lo difícil que es el camino para un Navegante. Sigue con el buen trabajo.\"",
  str_role_head_image_desc_1044 = "\"Resistir durante tanto tiempo es verdaderamente encomiable. ¡Sigamos entrenando juntos en el futuro!\"",
  str_role_head_image_desc_1045 = "\"Siempre recuerda: no importa cómo cambie el tiempo, la verdad perdura.\"",
  str_role_head_image_desc_1046 = "\"En los viajes por venir, siempre te mantendré a salvo.\"",
  str_role_head_image_desc_1047 = "\"¿Cuántas veces te he invitado a tomar el té de la tarde?\"",
  str_role_head_image_desc_1048 = "\"He compartido mi historia contigo; ¿cuál es la tuya?\"",
  str_role_head_image_desc_1049 = "\"¡Después de tanto tiempo juntos, ya somos verdaderos hermanos!\"",
  str_role_head_image_desc_1422 = "\"¡Croac! ¡Croac!! ¡Croac!!!\"",
  str_role_head_image_desc_1423 = "\"¿Qué debería hacer... La respuesta siempre ha estado en mi corazón?\"",
  str_role_head_image_frame_lock_condition_3052 = "Obtenido del evento Gerente por un Día",
  str_role_head_image_desc_frame_3052 = "\"La figura elegante encanta con su adorable pelusa, atrapando a otro en su encantadora red.\"",
  str_role_head_image_desc_1424 = "\"¡Bostezo! Me siento tan somnoliento desde el momento en que me cambié a estos pijamas.\"",
  str_role_head_image_lock_condition_role_1572 = "Obtained from the Manager for a Day event",
  str_role_head_image_desc_1572 = "\"Todos los ojos están puestos en ella; ella es el epítome de la perfección y el resplandor, la ídolo definitiva.\"",
  str_role_head_image_lock_condition_role_1573 = "Obtenido del evento Ecos de un Sueño.",
  str_role_head_image_desc_1573 = "\"Regalo este componente a Papá, deseando que su expresión se alinee con la que se muestra en la pantalla.\"",
  str_role_head_image_lock_condition_role_1574 = "Obtained from the Echoes of a Dream event.",
  str_role_head_image_desc_1574 = "\"Padre, por favor infórmame de tu ubicación actual.\"",
  str_role_head_image_desc_1425 = "\"¡Hola, Toto! El cálido Colossus acoge a todo trabajador con el corazón roto.\"",
  str_role_head_image_lock_condition_role_3751577 = "Obtenido del evento de Entrega a Tiempo.",
  str_role_head_image_lock_condition_role_3751579 = "Obtenido del evento Paz y Armonía.",
  str_role_head_image_frame_lock_condition_3763046 = "Obtenido del evento Paz y Armonía.",
  str_role_head_image_frame_lock_condition_3763047 = "Compra el libro de eventos especiales: Phase 22 Deluxe Edition para desbloquearlo.",
  str_role_head_image_desc_frame_3763046 = "\"Deseo que todo vaya a tu favor. Deseo que seas imparable. Deseo que logres todo lo que deseas. Deseo que siempre perseveres. ¡Deseo que siempre estés conmigo para que podamos compartir aún más momentos felices juntos!\"",
  str_role_head_image_desc_frame_3763047 = "Este estandarte tótem que es popular en toda la Isla de las Nubes es un símbolo de crecimiento y valentía.",
  str_role_head_image_desc_3751430 = "\"Muy bien. No manché mi honor hoy.\"",
  str_role_head_image_desc_3751577 = "\"Tu mirada debe ser aguda como la de un halcón, tus ataques deben ser tan afilados como sus garras y tus movimientos deben ser tan rápidos como sus alas al aletear.\"",
  str_role_head_image_desc_3751579 = "\"May todas las cosas en este mundo se prestan para la realización de tus deseos por toda la eternidad.\"",
  str_role_head_image_lock_condition_role_3751581 = "Obtenido del evento Ecos de un Sueño.",
  str_role_head_image_lock_condition_role_3751582 = "Obtenido del evento Ecos de un Sueño.",
  str_role_head_image_lock_condition_role_3751580 = "Obtenido del evento de inicio de sesión diario.",
  str_role_head_image_desc_3751581 = "\"Oh, ¿es esto... lo que se siente ser amado por alguien?\"",
  str_role_head_image_desc_3751582 = "\"Un bocado más... Sí, un bocado más!\"",
  str_role_head_image_desc_3751580 = "\"Soy el dueño de Hidden Fangs en Umbraton. ¡Bienvenido al mundo de los videojuegos!\"",
  str_role_head_image_frame_lock_condition_3763048 = "Obtenido del evento Imponente Dignidad.",
  str_role_head_image_frame_lock_condition_3763049 = "Compra el libro de eventos especiales: Phase 23 Deluxe Edition para desbloquearlo.",
  str_role_head_image_desc_frame_3763048 = "\"Pero no te preocupes. Nada puede permanecer igual para siempre, y aunque algunos cambios pueden pesarnos mucho, la mayoría de las veces, el cambio es emocionante.\"",
  str_role_head_image_desc_frame_3763049 = "\"¿Puede uno revelar los secretos custodiados por la Caja Negra con la tenue luz de una simple vela?\"",
  str_role_head_image_lock_condition_role_3751583 = "Obtenido del evento de Reporte de Deber del Nuevo Recluta.",
  str_role_head_image_lock_condition_role_3751584 = "Obtenido del evento de inicio de sesión del tercer aniversario.",
  str_role_head_image_lock_condition_role_3751585 = "Obtenido del evento Imponente Dignidad.",
  str_role_head_image_desc_3751436 = "\"¡Es maravilloso tenerlos a todos aquí!\"",
  str_role_head_image_desc_3751583 = "\"Necesitarás ser más fuerte. Más fuerte que los Aurorians más fuertes del mundo.\"",
  str_role_head_image_desc_3751584 = "\"Incluso si muero hoy, aún quiero ver tu verdadero rostro.\"",
  str_role_head_image_desc_3751585 = "\"Acercarse a él es perfectamente aceptable, pero les pido que se comporten con un poco más de dignidad. Después de todo, está aquí a mi solicitud.\"",
  str_role_head_image_desc_3751438 = "\"Los buscadores de la verdad son como aquellos que persiguen estrellas lejanas; requieren ojos sinceros para ver la luz.\"",
  str_role_head_image_desc_3751586 = "\"¡Confieso! ¡Expió! Yo... Yo soy el bendecido por la verdad.\"",
  str_role_head_image_desc_frame_3763050 = "\"May la Verdad te bendiga, y May tu vida de aquí en adelante brille intensamente.\"",
  str_role_head_image_lock_condition_role_3751438 = "Compra el paquete de regalo para obtenerlo.",
  str_role_head_image_lock_condition_role_3751586 = "Obtenido del evento Heartfelt Confession.",
  str_role_head_image_frame_lock_condition_3763050 = "Obtenido del evento Anniversary Sign-In.",
  str_role_head_image_desc_3751578 = "\"Ven, dilo conmigo ahora—¡Feliz Carnaval!\"",
  str_role_head_image_lock_condition_role_3751578 = "Obtenido en el evento Enfrentamiento Refrescante de Verano.",
  str_role_head_image_lock_condition_role_3751575 = "Obtenido del evento Diario de Aventura.",
  str_role_head_image_lock_condition_role_3751576 = "Obtenido del evento Flores Brillantes de Verano.",
  str_role_head_image_lock_condition_role_3751587 = "Obtenido del evento Ecos de un Sueño.",
  str_role_head_image_lock_condition_role_3751588 = "Obtenido del evento Ecos de un Sueño.",
  str_role_head_image_desc_3751426 = "\"¿Qué es esto? Qué conmovedor...\"",
  str_role_head_image_desc_3751427 = "\"Bienvenido de nuevo. ¿Cómo fue tu aventura? ¿Viste algo particularmente interesante?\"",
  str_role_head_image_desc_3751428 = "\"Ah, lo siento por dejarte ver un lado tan embarazoso de mí. Me aseguraré de mantener la compostura la próxima vez.\"",
  str_role_head_image_desc_3751575 = "\"¡A una nueva aventura!\"",
  str_role_head_image_desc_3751576 = "\"¡Pasar el verano con amigos es lo mejor!\"",
  str_role_head_image_desc_3751587 = "\"Ya que esta terquedad puede conquistar la tierra, enfrentarse al mar no debería ser un problema... ¿verdad?\"",
  str_role_head_image_desc_3751588 = "\"Bip-bip, activando el modo de navegación acuática...\"",
  str_role_head_image_desc_frame_3763051 = "\"Un anillo de natación a la moda que te hace querer abrazar el mar a primera vista. No te pierdas el fugaz verano—¡actúa rápido y úsalo para capturar la temporada!\"",
  str_role_head_image_desc_frame_3763044 = "\"Todos los que se bañen en esta luz sentirán que sus corazones se vuelven más brillantes.\"",
  str_role_head_image_desc_frame_3763045 = "\"¡Venir a Astra es la sorpresa más encantadora de este verano!\"",
  str_role_head_image_frame_lock_condition_3763051 = "Compra el libro de eventos especiales: Phase 24 Deluxe Edition para desbloquearlo.",
  str_role_head_image_frame_lock_condition_3763044 = "Obtenido del evento",
  str_role_head_image_frame_lock_condition_3763045 = "Obtained from the Summer's Sparkling Blossoms event.",
  str_role_head_image_lock_condition_role_3751589 = "Obtenido del evento Un Momento de Descanso.",
  str_role_head_image_desc_3751444 = "\"¡Mira a los competidores, totalmente comprometidos y luchando por sus rangos. Por favor, disfruta de este juego y muestra tu apoyo!\"",
  str_role_head_image_desc_3751443 = "\"Me encanta el agua y amo nadar. ¿Debería unirme a la competencia y divertirme con todos?\"",
  str_role_head_image_desc_3751589 = "\"Quiero tener un hermoso sueño, donde no hay tristeza y la felicidad dura para siempre...\"",
  str_role_head_image_desc_3751594 = "\"Las alas negras cortan el cielo sobre el Aqueronte como una cuchilla afilada.\"",
  str_role_head_image_desc_3751593 = "\"Ya sea por negocios o simplemente por diversión, con suficiente oro, ¡estoy a tu servicio!\"",
  str_role_head_image_desc_3751592 = "\"El juramento milenario no será olvidado. Un símbolo de gratitud del clan Longinus, otorgado solo a aquellos que completan el viaje de un verdadero héroe.\"",
  str_role_head_image_desc_3751591 = "\"No muestres piedad, mi espada está aquí para proteger los cuentos de las estrellas.\"",
  str_role_head_image_lock_condition_role_3751594 = "Obtenido del evento Saludos de Windelion.",
  str_role_head_image_lock_condition_role_3751593 = "Obtenido del evento Ambitious Proposal.",
  str_role_head_image_desc_frame_3763052 = "\"¡El oro es cegador!\"",
  str_role_head_image_desc_frame_3763053 = "\"Las alas negras son los guardianes de un juramento milenario.\"",
  str_role_head_image_frame_lock_condition_3763052 = "Obtenido del evento Ambitious Proposal.",
  str_role_head_image_frame_lock_condition_3763053 = "Compra el libro de eventos especiales: Phase 25 Deluxe Edition para desbloquearlo.",
  str_role_head_image_lock_condition_role_1777 = "Obtener de los eventos",
  str_role_head_image_desc_1777 = "¿Cómo será mi nuevo atuendo? ¡Estoy emocionado! ¡No puedo esperar para ponérmelo!"
}
return config
